// Deux formes : la notification S3 de MinIO, et un appel manuel. La clé S3 est
// encodée en URL et les espaces y sont des « + » — la décoder n'est pas une
// coquetterie, le service ne trouverait pas « 2026+programme.md ».
const entree = $json.body ?? $json;
let cle = null;

if (Array.isArray(entree.Records) && entree.Records.length > 0) {
  const brut = entree.Records[0]?.s3?.object?.key ?? null;
  if (brut) cle = decodeURIComponent(String(brut).replace(/\+/g, ' '));
}
cle = cle ?? entree.cle ?? entree.key ?? entree.programme ?? null;

if (!cle) {
  throw new Error(
    "aucune clé d'objet : attendu Records[0].s3.object.key (événement MinIO) " +
    "ou {\"cle\": \"programme.md\"} (appel manuel)"
  );
}
if (!/\.md$/i.test(cle)) {
  throw new Error("seuls les programmes .md sont traités, reçu : " + cle);
}

return [{ json: {
  service: "http://annales-service:8000",
  cle: cle,
  // La construction coûte ~3 $ en appels Opus : elle ne se déclenche pas sur
  // un dépôt accidentel. `forcer` doit être explicite.
  forcer: entree.forcer === true,
  etag: entree.Records?.[0]?.s3?.object?.eTag ?? null,
  recu_le: new Date().toISOString(),
}}];

// Garde-fou de dépense. Le rapprochement se fait sur la CLÉ de l'objet
// programme, inscrite dans origine.json par le service : c'est la seule
// information dont dispose le workflow — il ne télécharge pas le fichier et ne
// peut donc pas en calculer l'empreinte de contenu.
//
// Conséquence à connaître : redéposer un programme CORRIGÉ sous le même nom est
// bloqué lui aussi. C'est le bon défaut à 3 $ l'appel ; `forcer: true` passe
// outre.
const contexte = $("Normaliser l'événement").first().json;
const liste = $json?.referentiels ?? [];
const attendu = "programmes/" + contexte.cle;

const deja = liste.filter(r => (r?.origine?.programme ?? null) === attendu);

return [{ json: {
  ...contexte,
  deja_construit: deja.length > 0,
  empreintes_existantes: deja.map(r => r.empreinte),
  referentiels_connus: liste.length,
  reconstruire: contexte.forcer || deja.length === 0,
}}];

const c = $json;
return [{ json: {
  resultat: "ignoré",
  raison: "un référentiel a déjà été construit depuis ce programme",
  programme: c.cle,
  empreintes_existantes: c.empreintes_existantes,
  cout_evite_usd: 3,
  pour_reconstruire:
    "redéposer avec {\"cle\": \"" + c.cle + "\", \"forcer\": true} " +
    "sur le webhook /programme",
}}];

// On SIGNALE les sujets en attente, on ne les enchaîne pas : l'étiquetage se
// paie, et le référentiel qui vient d'être construit mérite d'être regardé
// avant qu'on mesure 2 000 questions contre lui.
const corpus = $json;
const tache = $("Vérifier la construction").first().json;
const contexte = $("Référentiel déjà construit ?").first().json;
const empreinte = tache?.resultat?.empreinte ?? null;

// Le contrôle final de l'étage 0 sépare INTÉGRITÉ (bloquant, code retour non
// nul) et GRANULARITÉ (avertissement, référentiel livré). Les seconds sont
// normaux sur une construction brute — ils se résorbent à la purge et à la
// confrontation — mais ils doivent être VUS, pas laissés dans stderr.
const journal = tache?.stderr ?? "";
const avertissements = journal.split("
")
  .filter(l => /^\s+·\s+\[/.test(l))
  .map(l => l.trim());

// Depuis que le contrôle final ne bloque plus, un défaut d'INTÉGRITÉ n'échoue
// plus la branche : il doit donc être remonté ici, sinon il ne serait vu de
// personne. Le référentiel est publié — c'est voulu, bloquer arrêtait toute la
// chaîne aval — mais publié n'est pas exempt.
const integrite = journal.split("
")
  .filter(l => /^\s+✗\s+\[/.test(l))
  .map(l => l.trim());

const enAttente = (corpus?.objets ?? [])
  .map(o => o.cle)
  .filter(c => /\.md$/i.test(c));

return [{ json: {
  resultat: integrite.length === 0 ? "réussi" : "réussi avec réserves",
  programme: contexte.cle,
  forcee: contexte.forcer === true,
  empreinte: empreinte,
  notions: tache?.resultat?.notions ?? null,
  signature_etiquetage: tache?.resultat?.signature_etiquetage ?? null,
  prefixe: tache?.resultat?.prefixe ?? null,
  duree_s: tache?.duree_s ?? null,
  avertissements_granularite: avertissements,
  defauts_integrite: integrite,
  note_integrite: integrite.length === 0 ? null
    : integrite.length + " défaut(s) d'intégrité : le référentiel est PUBLIÉ " +
      "quand même et ils sont recensés dans manifest.yaml sous `anomalies`. " +
      "Relancer etage0 construire --strict pour qu'ils fassent échouer la " +
      "commande, une fois la purge des annexes écrite.",
  note_granularite: avertissements.length === 0 ? null
    : "avertissements ATTENDUS à ce stade : mesurer la granularité avant la " +
      "purge des annexes et la confrontation au corpus revient à juger une " +
      "chaîne incomplète selon les critères de la chaîne complète.",
  sujets_en_attente: enAttente.length,
  sujets: enAttente.slice(0, 50),
  prochaine_etape: enAttente.length === 0
    ? "déposer des sujets dans le seau `corpus` — leur dépôt déclenchera le " +
      "workflow principal"
    : enAttente.length + " sujet(s) déjà dans `corpus` : ils ne seront PAS " +
      "traités automatiquement (leur dépôt est antérieur). Rejouer le webhook " +
      "/traiter pour chacun, ou appeler /extraire puis /etiqueter avec la " +
      "liste complète — le regroupement par combinaison de sections n'opère " +
      "qu'à l'intérieur d'un même appel.",
}}];

const tache = $json;
const contexte = $("Référentiel déjà construit ?").first().json;
const borne = tache.etat !== "echec" && tache.etat !== "interrompu";

return [{ json: {
  resultat: "échoué",
  etape: "construire",
  cause: borne ? "borne d'itérations atteinte (20 min), tâche toujours en cours"
               : (tache.erreur ?? "commande en échec"),
  etat_tache: tache.etat,
  tache: tache.id,
  code_retour: tache.code_retour ?? null,
  programme: contexte.cle,
  stderr: (tache.stderr ?? "").slice(-4000),
}}];
